const input=document.getElementById("text-input");async function sha256(t){const l=new TextEncoder().encode(t),r=await crypto.subtle.digest("SHA-256",l);return Array.from(new Uint8Array(r)).map(m=>m.toString(16).padStart(2,"0")).join("")}async function sha1(t){const l=new TextEncoder().encode(t),r=await crypto.subtle.digest("SHA-1",l);return Array.from(new Uint8Array(r)).map(m=>m.toString(16).padStart(2,"0")).join("")}function md5(t){const d=[];for(let n=0;n<64;n++)d[n]=Math.floor(Math.abs(Math.sin(n+1))*4294967296);const l=[7,12,17,22,7,12,17,22,7,12,17,22,7,12,17,22,5,9,14,20,5,9,14,20,5,9,14,20,5,9,14,20,4,11,16,23,4,11,16,23,4,11,16,23,4,11,16,23,6,10,15,21,6,10,15,21,6,10,15,21,6,10,15,21];function r(n){const i=[];for(let o=0;o<n.length*8;o+=8)i[o>>5]|=(n.charCodeAt(o/8)&255)<<o%32;return i}function m(n){const i="0123456789abcdef";let u="";for(let o=0;o<n.length*4;o++)u+=i.charAt(n[o>>2]>>o%4*8+4&15)+i.charAt(n[o>>2]>>o%4*8&15);return u}let y=r(t),h=1732584193,e=-271733879,s=-1732584194,a=271733878;y[t.length*8>>5]|=128<<t.length*8%32,y[(t.length*8+64>>>9<<4)+14]=t.length*8;for(let n=0;n<y.length;n+=16){let i=h,u=e,o=s,x=a;for(let c=0;c<64;c++){let f,g;c<16?(f=e&s|~e&a,g=c):c<32?(f=a&e|~a&s,g=(5*c+1)%16):c<48?(f=e^s^a,g=(3*c+5)%16):(f=s^(e|~a),g=7*c%16);let w=a;a=s,s=e,e=e+(h+f+d[c]+y[n+g]<<0),h=w;let p=e-u<<0;e=u+((p<<l[c]|p>>>32-l[c])<<0)}h=h+i<<0,e=e+u<<0,s=s+o<<0,a=a+x<<0}return m([h,e,s,a])}async function update(){const t=input.value;document.getElementById("sha256-out").textContent=t?await sha256(t):"-",document.getElementById("sha1-out").textContent=t?await sha1(t):"-",document.getElementById("md5-out").textContent=t?md5(t):"-"}input.addEventListener("input",update);function downloadResult(){const t=document.getElementById("sha256-out").textContent,d=document.getElementById("sha1-out").textContent,l=document.getElementById("md5-out").textContent;if(t==="-")return showToast(i18n.t("common.no_hash"));const r=[i18n.t("common.hash_title"),"",`SHA-256: ${t}`,`SHA-1:   ${d}`,`MD5:     ${l}`,"",i18n.t("common.hash_input"),input.value].join(`
`);downloadFile(r,"hash-results.txt")}function copyResult(t){const d=document.getElementById(t+"-out");d.textContent!=="-"&&copyToClipboard(d.textContent).then(()=>showToast(i18n.t("common.copied")))}
